    const ASPECTS = { auto: null, '16:9': 16 / 9, '1:1': 1, '9:16': 9 / 16, '4:3': 4 / 3 }
    const ASPECT_IDS = ['auto', '16:9', '1:1', '9:16', '4:3']
    const SCALE_IDS = [0.5, 1, 1.5, 2]

