    /**
     * Identity of the mounted preview document. The session id is part of the
     * token so two sessions at the same revision cannot share stale HTML.
     * The caller supplies the memoized content fingerprint so a same-revision
     * rewrite rebuilds the iframe without hashing the script on every render.
     * `codeIdentity` distinguishes the agent script from an applied local
     * draft even when both texts are byte-identical, so Apply always remounts.
     */
    function previewToken(sessionId, record, reloadTick, fingerprint, codeIdentity) {
      const token = String(sessionId) + ':' + String(record.sceneId) + ':'
        + String(record.revision) + ':' + String(reloadTick) + ':'
        + (typeof fingerprint === 'string' ? fingerprint : previewFingerprint(record))
      return typeof codeIdentity === 'string' && codeIdentity !== ''
        ? token + ':' + codeIdentity : token
    }

    /** cyrb53: a fast, synchronous 53-bit string hash with no dependencies. */
    function hashString(text, seed) {
      let h1 = 0xdeadbeef ^ seed
      let h2 = 0x41c6ce57 ^ seed
      for (let index = 0; index < text.length; index += 1) {
        const code = text.charCodeAt(index)
        h1 = Math.imul(h1 ^ code, 2654435761)
        h2 = Math.imul(h2 ^ code, 1597334677)
      }
      h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507)
      h1 ^= Math.imul(h2 ^ (h2 >>> 13), 3266489909)
      h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507)
      h2 ^= Math.imul(h1 ^ (h1 >>> 13), 3266489909)
      return 4294967296 * (2097151 & h2) + (h1 >>> 0)
    }

    /**
     * Content identity of a scene record: revision, title, and code. Two
     * records with equal identities may survive a host restart without a
     * rebuild; any byte of the rendered payload changing forces one.
     */
    function previewFingerprint(record) {
      if (record === null || record === undefined) return ''
      const revision = typeof record.revision === 'number' && Number.isFinite(record.revision)
        ? String(record.revision) : ''
      const title = typeof record.title === 'string' ? record.title : ''
      const code = typeof record.code === 'string' ? record.code : ''
      const payload = revision + '\u0000' + title + '\u0000' + code
      return hashString(payload, 0x9e3779b9).toString(36) + '.'
        + hashString(payload, 0x85ebca6b).toString(36)
    }

    // P3-2 history restore and revision diff constants. The Host has its own
    // independent copies; H11 asserts the shared scene limits agree.
    const HISTORY_MAX_REVISIONS = 12
    const RESTORE_RESPONSE_MAX_BYTES = 4096
    const RESTORE_TIMEOUT_MS = 20000
    const RESTORE_RECORD_RETRY_DELAYS = [500, 1500, 3000]
    const RESTORE_STALL_MS = 15000
    const DIFF_MAX_RESPONSE_BYTES = 2097152
    const DIFF_MAX_CODE_BYTES = 262144
    const DIFF_MAX_LINES = 4000
    const DIFF_MAX_CELLS = 16008001
    const DIFF_OP_TIMEOUT_MS = 15000
    const DIFF_DISPLAY_TITLE_POINTS = 200

    /** @returns the next monotonic operation token. */
    function nextHistoryToken(current) {
      return (Number.isSafeInteger(current) && current >= 0 ? current : 0) + 1
    }

    /** @returns the frozen restore request body in its exact key order. */
