let clock
const timeline = { playing: true, time: 0, speed: 1, loop: true, duration: 10, last: 0 }
let objectUids = new WeakMap()
let uidObjects = new Map()
const pins = new Map()
let scriptBaseline = new Map()
let unresolvedUids = []
let selectionHelpers = new Map()
const selectionHelperPool = []
let selectedUids = new Set()
let primarySelectedUid = null
let lockedUids = new Set()
let manualEntries = new Map()
let manualUids = new Set()
let deletedUids = new Set()
const removed = new Map()
const aliases = new Map()
let lastTimelineReport = 0
let selectionEnabled = false
let gizmo = null
let gizmoHelper = null
let gizmoMode = 'off'
let gizmoSpace = 'world'
let gizmoSnap = false
let draggingUid = null
let dragStartTransform = null
let dragResume = false
let lastGizmoReport = 0
let scriptCamera = null
let scriptRenderer = null
let scriptEnvironment = null
let environmentPin = null
let environmentBinding = null
