const MOUSE_TAP_SLOP = 4
const MOUSE_TAP_MAX_MS = 800
const TOUCH_TAP_SLOP = 10
const TOUCH_TAP_MAX_MS = 500
const LONG_PRESS_MS = 500
const MOUSE_GIZMO_SIZE = 0.85
