      '--twb-accent-line': 'rgba(79,124,255,.40)',
      '--twb-on-accent': '#f7f9ff',
      '--twb-warn': '#f0b35b',
      '--twb-warn-text': '#ffcf7a',
      '--twb-warn-ink': '#d9c7a6',
