      const onResetParamValues = props.onResetParamValues === undefined
        ? () => ({ ok: false, error: 'storage', record: null }) : props.onResetParamValues
      const onDurationOverride = props.onDurationOverride === undefined ? () => {} : props.onDurationOverride
      const onCreateManual = props.onCreateManual === undefined ? () => ({ ok: false, error: 'manual-invalid' }) : props.onCreateManual
      const onRemoveManual = props.onRemoveManual === undefined ? () => ({ ok: false, error: 'not-manual' }) : props.onRemoveManual
