      const storageNoticeHasRendererIssue = storageNotice !== null && Array.isArray(storageNotice.issues)
        && storageNotice.issues.some(issue => issue !== null && typeof issue === 'object' && issue.kind === 'invalid-renderer')
      const storageNoticeText = storageNotice === null
        ? null
        : storageNoticeHasRendererIssue
          ? t('editor.rendererInvalid') + ' ' + storageNotice.message
          : storageNotice.message
      const stepFps = props.stepFps === undefined ? 30 : props.stepFps
      const onStepFps = props.onStepFps === undefined ? () => {} : props.onStepFps
      const onAutoKeyPref = props.onAutoKey === undefined ? () => {} : props.onAutoKey
      const onPlaybackPref = props.onPlaybackPref === undefined ? () => {} : props.onPlaybackPref
      const onSheetPref = props.onSheetPref === undefined ? () => {} : props.onSheetPref
      const [viewRevision, setViewRevision] = React.useState(undefined)
      const { record, failed, missing: sceneMissing, revisions, latestRevision, viewingHistory, retryRecord } = useSceneFeed(sessionId, viewRevision)
      const [reloadTick, setReloadTick] = React.useState(0)
      const [status, setStatus] = React.useState('loading')
