              event.source.postMessage({ type: 'three-workbench:command', command: 'timeline', action: 'set-speed', speed: clock.speed }, '*')
              event.source.postMessage({ type: 'three-workbench:command', command: 'timeline', action: 'set-loop', loop: clock.loop }, '*')
              event.source.postMessage({ type: 'three-workbench:command', command: 'timeline', action: 'set-duration', duration: clock.duration }, '*')
              const lockedList = Object.keys(overridesRef.current.objects || {})
                .filter(uid => overridesRef.current.objects[uid] !== undefined && overridesRef.current.objects[uid] !== null
                  && overridesRef.current.objects[uid].locked === true)
              event.source.postMessage({ type: 'three-workbench:command', command: 'locks', uids: lockedList }, '*')
              // The embedded copy animates even if this resend is lost; the
              // authoritative record wins as soon as the runtime is ready.
