        const demoEditable = record !== null && record !== undefined && record.sceneId === 'demo'
          && viewingHistory !== true
        if (!latestActionsAllowed() && !demoEditable) return
        if (structuralBusyRef.current) {
          structuralNotice()
          return
        }
        const payload = {}
        const flags = reset !== null && reset !== undefined && typeof reset === 'object' ? reset : null
        if (flags !== null && Object.keys(flags).length > 0) payload.reset = flags
