        const snapped = snapTrackTime(Number(value), stepFpsRef.current)
        const raw = snapped === null ? Number(value) : snapped
        if (!Number.isFinite(raw)) return
        const time = Math.max(0, Math.min(duration > 0 ? duration : 0, raw))
