          padding: 0, boxSizing: 'border-box',
          borderRadius: 5, cursor: 'pointer', lineHeight: 1, color: '#e8edf4',
          border: '1px solid ' + (active ? (studioOn ? STUDIO_ACCENT_LINE : 'rgba(120,160,255,.75)') : 'rgba(255,255,255,.14)'),
