    const OVERLAY_BREAKPOINT = 776
    const TABLET_BAND_MAX = 1024
    const OVERLAY_MARKER_KEY = '__threeWorkbenchOverlay'
    const OVERLAY_MARKER_GENERATION_KEY = '__threeWorkbenchOverlayGeneration'
    const MARKER_SETTLE_TIMEOUT_MS = 1000

    /** The frame's left workbench column: reports its presentation to the layout. */
