      const overlayEntryLatch = props.useWorkbench(state => state.overlayEntryLatch === true)
      const overlayEntryLatchGeneration = props.useWorkbench(state => state.overlayEntryLatchGeneration || 0)
      const building = props.useWorkbench(state => state.building)
      const style = props.useWorkbench(state => state.style)
      const aspect = props.useWorkbench(state => state.aspect)
      const scale = props.useWorkbench(state => state.scale)
      const stepFps = props.useWorkbench(state => state.stepFps)
      const autoKey = props.useWorkbench(state => state.autoKey === true)
