        language: props.language,
        sessionId: props.sessionId,
        building,
        style,
        aspect,
        scale,
        stepFps,
        autoKey,
        speed,
        loop,
        dopeOpen,
        dopeHeight,
        dopeZoom,
        viewportWidth: props.viewportWidth,
