        onOverrideLive: (uid, fragment, node) => props.setOverrideLive(props.sessionId, uid, fragment, node),
        onBatchOverride: updates => props.batchOverride(props.sessionId, updates),
        onSetLock: (uid, node, locked) => props.setObjectLock(props.sessionId, uid, node, locked),
        onCameraOverride: camera => props.setCameraOverride(props.sessionId, camera),
        onRendererOverride: renderer => props.setRendererOverride(props.sessionId, renderer),
        onEnvironmentOverride: environment => props.setEnvironmentOverride(props.sessionId, environment),
        onClearOverrides: () => props.clearOverrides(props.sessionId),
        onSetParamValues: updates => props.setParamValues(props.sessionId, updates),
        onResetParamValues: keys => props.resetParamValues(props.sessionId, keys),
        onDurationOverride: duration => props.setTimelineDuration(props.sessionId, duration),
        getEditorRecord: () => props.getEditorRecord(props.sessionId),
