    /** Chat row for one `three_scene` result; opens the workbench column. */
    function SceneCard(props) {
      const t = props.t
      const phase = props.phase
      const block = props.block
      const meta = phase === 'result' && block && block.meta && typeof block.meta === 'object' ? block.meta : undefined
      const sceneId = meta && typeof meta.sceneId === 'string' ? meta.sceneId : undefined
      const revision = meta && typeof meta.revision === 'number' ? meta.revision : undefined
      const title = meta && typeof meta.title === 'string' ? meta.title : undefined
      const sawPending = React.useRef(false)
      const autoOpened = React.useRef(false)

      // The tool card mounts while arguments stream. Only a result observed
      // arriving after that mount is new; a rehydrated result is already
      // complete and must not reopen a preview the user closed (N1).
      React.useEffect(() => {
        if (phase !== 'result') sawPending.current = true
      }, [phase])

      React.useEffect(() => {
        if (autoOpened.current) return
        if (!shouldAutoOpenScene({
          phase,
          sceneId,
          resultTime: block ? block.time : undefined,
          now: Date.now(),
          pluginLoadedAt: PLUGIN_LOADED_AT,
          sawPending: sawPending.current,
        })) return
        autoOpened.current = true
        props.openWorkbench()
      }, [phase, sceneId, revision, title])

      // The tool card mounts as soon as the model starts emitting the call, so
      // it is the only signal the preview pane has while the scene is written.
      React.useEffect(() => {
        props.setBuilding(props.callId, phase !== 'result')
        return () => props.setBuilding(props.callId, false)
      }, [phase])

      const pending = phase !== 'result' || sceneId === undefined
      return h('div', {
        style: { display: 'flex', alignItems: 'center', gap: 10, margin: '6px 0', padding: '8px 10px',
          border: '1px solid color-mix(in srgb, currentColor 16%, transparent)', borderRadius: 8,
          background: 'color-mix(in srgb, currentColor 4%, transparent)' },
      },
      h('div', {
        style: { width: 26, height: 26, borderRadius: 7, flex: '0 0 auto',
          background: 'linear-gradient(135deg, #4f7cff, #9b5cff)' },
      }),
      h('div', { style: { minWidth: 0, flex: 1, display: 'flex', flexDirection: 'column', gap: 1 } },
        h('div', { style: { fontSize: 12, fontWeight: 600, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' } },
          pending ? t('card.pending') : (title || t('card.title'))),
        h('div', { style: { fontSize: 10, fontFamily: mono, opacity: .6 } },
          revision === undefined ? '' : t('card.revision', { revision }))),
      pending ? null : h('button', { type: 'button', style: buttonStyle, onClick: props.openWorkbench }, t('action.open')))
    }

    /** Conversation-header button that brings the workbench back after closing. */
